AND COALESCE(p.direction, 'receivable') = 'receivable'

	AND (p.pay_deadline >= CURDATE() OR p.pay_status = '1')


	AND p.pay_deadline < CURDATE()
	AND COALESCE(p.pay_status, '0') != '1'


	AND p.park_id = #{query.parkId}


	AND p.payment_id = #{query.paymentId}


	AND c.customer_name LIKE CONCAT('%', #{query.customerName}, '%')


	AND (
		CONCAT('ZD', p.payment_id) LIKE CONCAT('%', #{query.paymentNo}, '%')
		OR CAST(p.payment_id AS CHAR) LIKE CONCAT('%', #{query.paymentNo}, '%')
		OR n.notice_no LIKE CONCAT('%', #{query.paymentNo}, '%')
	)


	AND COALESCE(n.sms_status, 'pending') = #{query.smsStatus}


	AND COALESCE(n.email_status, 'pending') = #{query.emailStatus}


	AND COALESCE(n.inbox_status, 'pending') = #{query.inboxStatus}


	AND COALESCE(n.miniapp_status, 'pending') = #{query.miniappStatus}


	AND c.building_name = #{query.buildingName}


	AND DATE(COALESCE(n.create_time, p.create_time, p.pay_deadline)) >= #{query.createStartDate}


	AND DATE(COALESCE(n.create_time, p.create_time, p.pay_deadline)) <= #{query.createEndDate}
